mapper.select:
WITH RECURSIVE dept_tree AS ( -- 初始查询：查找指定父部门 SELECT id, name, code, parent_id, level, status, manager_id, location, establish_date FROM t_department WHERE parent_id = #{parentId}
UNION ALL
-- 递归查询：查找子部门的子部门 SELECT d.id, d.name, d.code, d.parent_id, d.level, d.status, d.manager_id, d.location, d.establish_date FROM t_department d INNER JOIN dept_tree dt ON d.parent_id = dt.id) SELECT * FROM dept_tree ORDER BY level, name

SELECT d.id, d.name, d.code, d.parent_id, d.description, d.manager_id, d.location, d.level, d.status, d.establish_date, d.extra_info, e.name as manager_name, (SELECT COUNT(*) FROM t_employee WHERE department_id = d.id) as employee_count FROM t_department d LEFT JOIN t_employee e ON d.manager_id = e.id
AND d.name LIKE CONCAT('%', #{name}, '%')
AND d.code = #{code}
AND d.parent_id = #{parentId}
AND d.manager_id = #{managerId}
AND d.location LIKE CONCAT('%', #{location}, '%')
AND d.level = #{level}
AND d.status = #{status}
AND d.establish_date >= #{establishDateStart}
AND d.establish_date <= #{establishDateEnd}
ORDER BY d.level, d.name

SELECT d.id, d.name, d.code, d.level, d.status, COUNT(e.id) as totalEmployees, COUNT(CASE WHEN e.status = 'ACTIVE' THEN e.id END) as activeEmployees, COUNT(CASE WHEN e.status = 'RESIGNED' THEN e.id END) as resignedEmployees, COUNT(p.id) as projectCount, SUM(e.base_salary) as totalSalary, AVG(e.base_salary) as averageSalary FROM t_department d LEFT JOIN t_employee e ON d.id = e.department_id LEFT JOIN t_project p ON d.id = p.department_id AND p.status IN ('RUNNING', 'COMPLETED')
AND d.parent_id = #{parentId}
AND d.level = #{level}
AND d.status = #{status}
GROUP BY d.id, d.name, d.code, d.level, d.status ORDER BY d.level, d.name
